        let s = i;
        if (l < size && hv[l] < hv[s]) s = l;
        if (r < size && hv[r] < hv[s]) s = r;
        if (s === i) break;
        const tv = hv[i]; hv[i] = hv[s]; hv[s] = tv;
        const tf = hf[i]; hf[i] = hf[s]; hf[s] = tf;
        i = s;
      }
    }
    return [v, f];
