  // Os pesos extraídos saem em ordem crescente; casar com T descrescente
  // a partir da posição m (os m maiores carros ficam com peso 0).
  let ans = 0n;
  for (let k = 0; k < K; k++) {
    const [v, f] = pop();
    ans += BigInt(T[m + k]) * BigInt(v);
    push(v + f, f);
  }

  console.log(ans.toString());
}

